ll lcm(ll a, ll b){
    return a / __gcd(a, b) * b;
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> x;
    ll ans;
    for(ll i = 1 ; i * i <= x ; i++){
        if(x % i == 0 && lcm(i, x / i) == x){
            ans = i;
        }
    }
    cout << ans << " " << x / ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
#define finish(x) return cout << x << endl, 0
#define ll long long

int n;
vector <int> a;

int solve(vector <int> &c, int bit){
    if(bit < 0) return 0;
    vector <int> l, r;
    for(auto &i : c){
        if(((i >> bit) & 1) == 0) l.push_back(i);
        else r.push_back(i);
    }
    if(l.size() == 0) return solve(r, bit - 1);
    if(r.size() == 0) return solve(l, bit - 1);
    return min(solve(l, bit - 1), solve(r, bit - 1)) + (1 << bit);
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n;
    a.resize(n);
    for(auto &i : a) cin >> i;
    cout << solve(a, 30) << endl;
}

#include <bits/stdc++.h>

#define forn(i, n) for (int i = 0; i < int(n); i++)
#define x first
#define y second

using namespace std;

const int INF = 2e9;

typedef pair<int, int> pt;
map<int, int> ls;

int get(vector<pt> a){
	int cnt = 0;
	int l = -INF, r = -INF;
	sort(a.begin(), a.end());
	forn(i, a.size()){
		if (a[i].x > r){
			if (r != -INF)
				ls[l] = 0;
			++cnt;
			l = a[i].x, r = a[i].y;
		}
		else{
			r = max(r, a[i].y);
		}
	}
	ls[l] = 0;
	return cnt;
}

void process(vector<pair<int, pt>> &qr, vector<int> &ans){
	set<int> open;
	forn(i, qr.size()){
		vector<int> op, cl;
		int j = i - 1;
		while (j + 1 < int(qr.size()) && qr[j + 1].x == qr[i].x){
			++j;
			if (qr[j].y.x == 1)
				op.push_back(qr[j].y.y);
			else
				cl.push_back(qr[j].y.y);
		}
		if (open.size() == 1 && !op.empty()){
			++ans[*open.begin()];
		}
		for (auto it : op){
			open.insert(it);
		}
		for (auto it : cl){
			open.erase(it);
		}
		i = j;
	}
}

void solve(){
	int n;
	scanf("%d", &n);
	vector<pt> a(n);
	forn(i, n) scanf("%d%d", &a[i].x, &a[i].y);

	vector<pair<int, pt>> qr;
	forn(i, n){
		qr.push_back({a[i].x, {1, i}});
		qr.push_back({a[i].y, {-1, i}});
	}
	sort(qr.begin(), qr.end());

	vector<int> ans(n, 0);
	ls.clear();
	int cur = get(a);

	process(qr, ans);
	forn(i, n) if (ls.count(a[i].x)) ++ls[a[i].x];
	forn(i, n) if (ls[a[i].x] == 1) --ans[i];

	printf("%d\n", *max_element(ans.begin(), ans.end()) + cur);
}

int main(){
	int tc;
	scanf("%d", &tc);
	forn(i, tc)
		solve();
}

#include <bits/stdc++.h>
using namespace std;
#define MX 100000
int arr[100005],u[MX+5],cnt[MX+5];
vector<int> d[MX+5];
bool b[MX+5];
int coprime(int x)
{
	int ret=0;
	for (int i:d[x])
	ret+=cnt[i]*u[i];
	return ret;
}
void update(int x,int a)
{
	for (int i:d[x])
	cnt[i]+=a;
}
int main()
{
	for (int i=1;i<=MX;i++)
	{
		for (int j=i;j<=MX;j+=i)
		d[j].push_back(i);
		if (i==1)
		u[i]=1;
		else if ((i/d[i][1])%d[i][1]==0)
		u[i]=0;
		else
		u[i]=-u[i/d[i][1]];
	}
	int n;
	scanf("%d",&n);
	long long ans=0;
	for (int i=0;i<n;i++)
	{
		int a;
		scanf("%d",&a);
		ans=max(ans,(long long)a);
		b[a]=1;
	}
	for (int g=1;g<=MX;g++)
	{
		stack<int> s;
		for (int i=MX/g;i>0;i--)
		{
			if (!b[i*g])
			continue;
			int c=coprime(i);
			while (c)
			{
				if (__gcd(i,s.top())==1)
				{
					ans=max(ans,1LL*i*s.top()*g);
					c--;
				}
				update(s.top(),-1);
				s.pop();
			}
			update(i,1);
			s.push(i);
		}
		while (!s.empty())
		{
			update(s.top(),-1);
			s.pop();
		}
	}
	printf("%I64d",ans);
}
